import {faultCatalog} from './energy-faults.mjs';
import {examCorrect} from './energy-exam-model.mjs';
export const energyExamScore=e=>Math.round(e.cases.filter((c,i)=>examCorrect(c,e.answers[i])).length/3*100);
export function validEnergyExam(e){return e&&typeof e.id==='string'&&e.status==='finished'&&Number.isFinite(Date.parse(e.finishedAt))&&Array.isArray(e.cases)&&e.cases.length===3&&new Set(e.cases.map(c=>c.lab)).size===3&&e.cases.every(c=>faultCatalog[c.lab]&&['basic','combined','intermittent'].includes(c.level)&&Array.isArray(c.faults)&&c.faults.length>0&&c.faults.every(f=>faultCatalog[c.lab].some(x=>x.id===f)))&&Array.isArray(e.answers)&&e.answers.length===3&&e.answers.every((a,i)=>Array.isArray(a)&&a.every(f=>faultCatalog[e.cases[i].lab].some(x=>x.id===f)));}
export function createEnergyExamHistory(storage){const key='mecanica.energy-exam-history.v1';let rows=[],warning='';try{const s=JSON.parse(storage.getItem(key)||'[]');if(!Array.isArray(s))throw Error();rows=s.filter(validEnergyExam).slice(-50);}catch{warning='No se pudo leer el archivo de exámenes.';}return {all:()=>structuredClone(rows),warning:()=>warning,add(e){if(!validEnergyExam(e)||rows.some(r=>r.id===e.id))return;rows.push(structuredClone(e));rows=rows.slice(-50);try{storage.setItem(key,JSON.stringify(rows));}catch{warning='El archivo de exámenes está disponible solo durante esta sesión.';}}};}
export function energyMastery(exams){return Object.entries(faultCatalog).flatMap(([lab,fs])=>fs.map(f=>{const answers=[];for(const e of exams){const i=e.cases.findIndex(c=>c.lab===lab);if(i<0)continue;const c=e.cases[i],selected=e.answers[i].includes(f.id),present=c.faults.includes(f.id);if(present||selected)answers.push({id:e.id,correct:selected===present});}const recent=answers.slice(-5),correct=recent.filter(x=>x.correct).length;return {lab,label:f.label,n:answers.length,recent:recent.length,correct,errors:answers.filter(x=>!x.correct).length,status:recent.length<3?'Faltan datos':correct===recent.length?'Aciertos consistentes':correct/recent.length>=.6?'En progreso':'Prioridad de repaso'};})).filter(x=>x.n);}
